!solve(input){ 
    let len = input.length; 
    let output = []; 
    for(let i=0; i<len; i++){ 
        output.push(input[i]); 
    } 
    for(let i=0; i<len-1; i++){ 
        for(let j=i+1; j<len; j++){ 
            if(output[i] > output[j]){ 
                let temp = output[i]; 
                output[i] = output[j]; 
                output[j] = temp; 
            } 
        } 
    } 
    return output; 
}

!solve(input){ 
    let arr = input.arr; 
    let target = input.target; 
    let left = 0; 
    let right = arr.length - 1; 
    while (left <= right) { 
        let mid = Math.floor((left + right) / 2); 
        if (arr[mid] === target) { 
            return mid; 
        } else if (arr[mid] < target) { 
            left = mid + 1; 
        } else { 
            right = mid - 1; 
        } 
    } 
    return -1; 
}

